#!/usr/bin/env node
// Fabric update tests must prove Journal generation without rewriting the
// tracked public/journal mirror. All generated bytes stay inside a unique
// private temporary directory, which is removed after verification.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {verifyJournalBuild} from '../systemia/newsroom/journal-build-verifier.mjs';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const journalOrigin='https://fabric.systemiacommandcenters.com/journal';
const workDir=fs.mkdtempSync(path.join(os.tmpdir(),'evercraft-fabric-journal-test-'));
try{
  const build=spawnSync(process.execPath,[
    path.join(root,'systemia/newsroom/journal-publisher.mjs'),
    path.join(root,'systemia/newsroom/stories'),
    workDir
  ],{
    cwd:root,
    encoding:'utf8',
    env:{...process.env,EVERCRAFT_JOURNAL_ORIGIN:journalOrigin},
    timeout:90000,
    maxBuffer:1024*1024
  });
  if(build.error)throw build.error;
  if(build.status!==0){
    process.stderr.write('FABRIC_JOURNAL_ISOLATED_BUILD_FAILED\n');
    if(build.stderr)process.stderr.write(build.stderr.slice(0,1000)+'\n');
    process.exitCode=1;
  }else{
    const proof=verifyJournalBuild({root:workDir,expectedOrigin:journalOrigin});
    process.stdout.write(JSON.stringify({
      schema:'evercraft.fabric.journal-isolated-test.v1',
      verified:true,
      output_destination:'private_temporary_directory',
      tracked_journal_written:false,
      journal_source_authority:'checked_in_story_sources',
      journal_verification:proof.schema||'verified'
    })+'\n');
  }
}catch(error){
  process.stderr.write('FABRIC_JOURNAL_ISOLATED_PROOF_HOLD '+String(error?.message||error)+'\n');
  process.exitCode=1;
}finally{
  fs.rmSync(workDir,{recursive:true,force:true});
}
